import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { roomAPI } from '../services/api';

const Home = () => {
  const [rooms, setRooms] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchFeaturedRooms();
  }, []);

  const fetchFeaturedRooms = async () => {
    try {
      const response = await roomAPI.getAll({ limit: 3 });
      setRooms(response.data.rooms);
    } catch (error) {
      console.error('Erreur chargement salles:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="main-content">
      {/* Section Hero */}
      <div className="card hero-section">
        <h1 className="hero-title">Bienvenue sur la plateforme de réservation de salles</h1>
        <p className="hero-subtitle">
          Réservez la salle parfaite pour vos réunions, conférences ou événements.
          Des espaces professionnels dans toute l'Algérie.
        </p>
        
        <div className="cta-buttons">
          <Link to="/rooms" className="btn btn-primary">
            Voir toutes les salles
          </Link>
          <Link to="/register" className="btn btn-secondary">
            Créer un compte
          </Link>
        </div>
      </div>

      {/* Salles populaires */}
      <div className="card">
        <h2 style={{ textAlign: 'center', marginBottom: '1.5rem' }}>Salles populaires</h2>
        {loading ? (
          <p style={{ textAlign: 'center' }}>Chargement des salles...</p>
        ) : rooms.length > 0 ? (
          <div className="rooms-grid">
            {rooms.map(room => (
              <div key={room.id} className="room-card">
                <div className="room-content">
                  <h3 className="room-title">{room.title}</h3>
                  <p className="room-location">
                    📍 {room.city} • 👥 {room.capacity} personnes
                  </p>
                  <p className="room-description">
                    {room.description?.substring(0, 100) || 'Salle professionnelle équipée pour vos réunions...'}
                  </p>
                  <div className="room-meta">
                    <span>📍 {room.city}</span>
                    <span>👥 {room.capacity} pers.</span>
                  </div>
                  <div className="room-footer">
                    <span className="room-price">{room.price_per_hour}€/heure</span>
                    <Link to={`/rooms/${room.id}`} className="btn btn-primary btn-sm">
                      Voir détails
                    </Link>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="empty-state">
            <p>Aucune salle disponible pour le moment.</p>
            <Link to="/register" className="btn btn-primary">
              Devenir propriétaire
            </Link>
          </div>
        )}
      </div>

      {/* Fonctionnalités */}
      <div className="card features">
        <h2 style={{ textAlign: 'center', marginBottom: '2rem' }}>Pourquoi choisir notre plateforme ?</h2>
        <div className="features-grid">
          <div className="feature">
            <h3>🏢 Large choix</h3>
            <p>Des salles de toutes tailles et pour tous les budgets</p>
          </div>
          <div className="feature">
            <h3>📍 Localisation</h3>
            <p>Des salles bien situées dans les centres-villes</p>
          </div>
          <div className="feature">
            <h3>💰 Transparence</h3>
            <p>Pas de frais cachés, prix affichés à l'heure</p>
          </div>
          <div className="feature">
            <h3>🔒 Sécurité</h3>
            <p>Paiement sécurisé et système de confiance</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Home;
